ee:message.ee:set-payload:
%dw 2.0
import appendNamespace from modules::utilitaries
output text/xml
ns soapenv http://schemas.xmlsoap.org/soap/envelope/
ns col Collection_Siebel
---
soapenv#Envelope: {
    soapenv#Header: {},
    soapenv#Body: {
        col#RegistroTramiteMasivo: {
        	col#Origen: payload.Origen,
            col#DatosRegistro: {
            	col#RequestRegistroTramiteMasivo: payload.DatosRegistro.RequestRegistroTramiteMasivo map ((item, index) -> {
                    col#Pedido: item.Pedido  default null,
            		col#Abonado: item.Abonado default null,
            		col#TipoTramite: item.TipoTramite default null,
            		col#FechaIngresoTramite: item.FechaIngresoTramite default null,
            		col#TipoDocumento: item.TipoDocumento default null,
            		col#NumeroDocumento: item.NumeroDocumento default null,
            		col#CuentaFacturacion: item.CuentaFacturacion default null,
            		col#CuentaServicio: item.CuentaServicio default null,
            		col#IdTransaccion: item.IdTransaccion default "?",
            		col#sMotivo: item.sMotivo default "?",
            		col#FechaOperacion: item.FechaOperacion default "?"
                })
            }
        }
    }
}

%dw 2.0
output application/json
var tramits = payload..*RespuestaTramiteMasivo
---
{
  "System": {
    "correlationID": vars.inputData.correlationId,
    "processingServer": vars.inputData.processingServer,
    "responseDate": now()
  },
  Response: {
    ResponseTramits: 
        tramits map () -> {
            orderNumber: $.NumeroPedido,
            responseCode: $.CodigoRespuesta,
            responseDescription: $.DescripcionRespuesta,
        }
    }
}
